ragraph","content":[{"type":"text","text":"$0"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"TTM Net Income (with impairments)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"-$63.8 million"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"TTM FCF (excluding impairments)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$18.6 million"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Share Buyback Program"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$50 million authorized ($40.5 million remaining)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"1-month performance"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"+32%"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"EV/FCF"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"-6.4 (i.e. negative EV due to high net cash)"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Agora (API) shows how accounting noise and a battered growth narrative can obscure hidden value. Its stock has crashed ~95% from 2021 highs, but it now trades below net cash. Large impairment charges and restructuring costs hide the fact that it’s still cash flow positive, with share buybacks and a balance sheet that could outlast years of market negativity."}]},{"type":"paragraph","content":[{"type":"text","text":"This is the type of micro-cap that could double or triple quickly if sentiment flips."}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Business: More Than Just Video Calls"}]},{"type":"paragraph","content":[{"type":"text","text":"Agora offers programmable APIs powering:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Real-time voice/video chat"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interactive livestreaming"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Low-latency broadcasting"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"AI-driven audio/video processing"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Their customers include social apps, gaming platforms, e-commerce streaming, and online education services."}]},{"type":"paragraph","content":[{"type":"text","text":"Why the collapse?","marks":[{"type":"bold"}]},{"type":"text","text":" Pandemic tailwinds reversed. Growth slowed. Agora’s top-line shrank from $175 million in 2021 to ~$137 million in 2024. Also, they recorded huge impairments from a failed acquisition:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"EasyChat (acquired 2021):","marks":[{"type":"bold"}]},{"type":"text","text":" Agora paid ~$110 million for a Chinese social app aiming to boost revenue in China. The government’s tech crackdown and declining app usage forced Agora to impair nearly the entire investment."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This has left the stock battered and trading at absurdly cheap multiples."}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Hidden Value Thesis"}]},{"type":"paragraph","content":[{"type":"text","text":"Two key drivers spark my interest:","marks":[{"type":"bold"}]}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Massive net cash position","marks":[{"type":"bold"}]},{"type":"text","text":" – Agora holds ~$286 million cash and no debt, exceeding its entire market cap."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Core business still generates cash","marks":[{"type":"bold"}]},{"type":"text","text":" – TTM operating cash flow remains positive even after impairments and restructuring."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Let’s break that down."}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Catalyst #1: The Impairment Charges Are Done"}]},{"type":"paragraph","content":[{"type":"text","text":"The $105.7 Million EasyChat Mistake","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"From their latest filings:"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"“During 2023, the Company determined that the EasyChat unit’s carrying value was no longer recoverable due to lower usage, monetization challenges, and regulatory uncertainty.”"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Impairment summary:"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Type"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Amount"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Goodwill impairment"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$45.2 million"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Intangibles impairment"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$60.5 million"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Total impairment"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$105.7 million"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"These impairments smashed net income:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"2023 Net Income: "},{"type":"text","text":"-$89.2 million","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"2024 Net Income: "},{"type":"text","text":"-$63.8 million","marks":[{"type":"bold"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Yet cash flow remains positive. These non-cash write-downs are flowing through the income statement, obscuring the true operating picture."}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Catalyst #2: Aggressive Share Buybacks"}]},{"type":"paragraph","content":[{"type":"text","text":"Agora authorized a "},{"type":"text","text":"$50 million share repurchase program","marks":[{"type":"bold"}]},{"type":"text","text":" in December 2024. They’ve already deployed ~19% of that:"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Buybacks"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Value"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Total authorized"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$50 million"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Spent to date"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$9.5 million"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Remaining"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$40.5 million"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"At current prices, even modest repurchases are highly accretive. For instance, with a ~$167 million market cap, the authorized $50M buyback could theoretically retire nearly "},{"type":"text","text":"30% of the float","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Management explicitly stated in earnings calls:"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"“We believe our current market valuation does not reflect our cash position or long-term prospects.”"}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Catalyst #3: Cost Restructuring"}]},{"type":"paragraph","content":[{"type":"text","text":"Agora launched restructuring in early 2025:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Target Savings:","marks":[{"type":"bold"}]},{"type":"text","text":" $10–$12 million annually"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Timeline:","marks":[{"type":"bold"}]},{"type":"text","text":" Full impact by late 2025"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Headcount reductions, data center optimization, lower sales & marketing"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Even modest savings could boost free cash flow significantly:"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Scenario"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Potential Annual FCF Increase"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Low-end savings ($10M)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"+$10M"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":