":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Metric"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Value"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Market Cap"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$167M"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Net Cash"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"$286M"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Enterprise Value"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"-$119M"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This implies a negative EV","marks":[{"type":"bold"}]},{"type":"text","text":", meaning you’re getting the business for free—and getting paid ~$119 million to own it."}]},{"type":"paragraph","content":[{"type":"text","text":"Here’s a quick valuation look:"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Bear Case"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"FCF = $10M"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"EV = $0 (net cash supports valuation)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Implied P/FCF: 16.7× → ~$2.12/share fair value"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Base Case"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"FCF = $18M (TTM)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Modest growth: 5%"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"EV/FCF = 10× → $180M EV"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fair value: ~$4.60/share (+175%)"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Bull Case"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"FCF = $28M (includes $10M restructuring savings)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Growth = 8% CAGR"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"EV/FCF = 12× → $336M EV"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fair value: ~$7.22/share (+330%)"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Even conservative estimates suggest "},{"type":"text","text":"fair value ~2–3× above current price","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why This Setup Interests Me"}]},{"type":"paragraph","content":[{"type":"text","text":"This is the perfect micro-cap mispricing:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Massive net cash","marks":[{"type":"bold"}]},{"type":"text","text":" shields downside."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Accounting impairments","marks":[{"type":"bold"}]},{"type":"text","text":" obscure positive cash flow."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The business is "},{"type":"text","text":"still profitable on a cash basis.","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ongoing buybacks provide a strong floor."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"While there’s no guarantee the core business will reaccelerate, the cash alone provides a margin of safety."}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Bottom Line"}]},{"type":"paragraph","content":[{"type":"text","text":"Agora is trading below its net cash, an anomaly rarely seen in public markets. Like ZDGE, it’s a textbook case where "},{"type":"text","text":"accounting noise and investor fatigue hide real value.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"It’s not risk-free:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chinese exposure remains a political/regulatory overhang."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Revenue has stagnated."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The EasyChat acquisition showed questionable capital allocation."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"But for those willing to dig through the numbers, Agora might be a hidden gem."}]},{"type":"paragraph","content":[{"type":"text","text":"At worst, you’re buying cash at a discount. At best, you’re getting a profitable SaaS business thrown in for free.","marks":[{"type":"bold"}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Key Takeaway"}]},{"type":"paragraph","content":[{"type":"text","text":"This is the type of setup I love in micro-caps:"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"“Negative EV. Positive cash flow. Management buying shares. Market ignoring it.”"}]}]},{"type":"paragraph","content":[{"type":"text","text":"It’s risky. But the risk-reward looks compelling for those with patience."}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","text":"Disclaimer: This article is for educational purposes only and not financial advice. Do your own research before investing.","marks":[{"type":"italic"}]}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","text":"Sources:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Agora, Inc. SEC filings (10-K, 10-Q)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Yahoo Finance"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"TradingView"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Company earnings calls"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Personal analysis"}]}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"written by Eeshan Karra"}]}]}]}'::jsonb,
